'use strict';

const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(Number(n||0))+' ₽';const num=n=>new Intl.NumberFormat('ru-RU').format(Number(n||0));
const fmtDate=v=>{if(!v)return'—';const d=new Date(String(v).includes('T')?v:String(v)+'T12:00:00');return Number.isNaN(d.getTime())?esc(v):new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)};
const fmtDateTime=v=>{if(!v)return'—';const raw=String(v),d=new Date(raw.includes('T')?raw:raw.replace(' ','T'));return Number.isNaN(d.getTime())?esc(raw):new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d)};
const allowedPhotoTypes=new Set(['image/jpeg','image/png','image/webp']);
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
async function filesToPayload(input){const files=[...(input?.files||[])];if(files.length>5)throw new Error('Не более 5 фотографий за один раз');const out=[];for(const f of files){if(!allowedPhotoTypes.has(f.type))throw new Error('Разрешены JPG, PNG и WEBP');if(f.size>4_000_000)throw new Error('Одна фотография должна быть меньше 4 МБ');out.push({name:f.name,type:f.type,data:await fileToDataURL(f)});}return out;}
function roleLabel(r){return({owner:'Владелец',admin:'Администратор',inspector:'Инспектор',manager:'Менеджер',technician:'Техник',tenant:'Арендатор'}[r]||r);}
function hasPerm(p){return app.user?.role==='owner'||(app.user?.permissions||[]).includes('*')||(app.user?.permissions||[]).includes(p);}
function canManageStaff(){return app.user?.role==='owner'||hasPerm('staff_manage');}
function staffMode(){return app.user&&app.user.role!=='tenant';}
function photoGrid(photos=[],showLabel=false){if(!photos.length)return'<div class="photo-empty">Фотографий пока нет</div>';return`<div class="photo-grid">${photos.map(p=>`<a class="photo-tile" href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Фото" loading="lazy"><span>${showLabel&&p.label?`<b>${esc(p.label)}</b><br>`:''}${fmtDateTime(p.at)}<br><b>${esc(p.actor||'')}</b></span></a>`).join('')}</div>`;}

const statusMap={new:'Новая',assigned:'Назначена',in_progress:'В работе',inspection:'На проверке',overdue:'Просрочена',awaiting_acceptance:'Ожидает подтверждения',done:'Выполнена'};
const priorityMap={low:'Низкий',normal:'Обычный',high:'Высокий',critical:'Критический'};
const inspectionStatusMap={ok:'Норма',attention:'Есть замечания',critical:'Критично'};
const app={user:null,csrf:null,view:'dashboard',data:{},selectedTenant:null,selectedIssue:null};

async function api(url,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(app.csrf&&options.method&&options.method!=='GET')headers['X-CSRF-Token']=app.csrf;const r=await fetch(url,{credentials:'same-origin',...options,headers});let data={};try{data=await r.json();}catch{}if(r.status===401&&url!='/api/login'){app.user=null;renderLogin();throw new Error('AUTH_REQUIRED');}if(!r.ok){const e=new Error(data.error||'REQUEST_FAILED');e.code=data.error;e.status=r.status;throw e;}return data;}
function toast(t){const el=document.createElement('div');el.className='toast';el.textContent=t;document.body.appendChild(el);setTimeout(()=>el.remove(),3200);}
function registerSW(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
async function boot(){registerSW();try{const me=await api('/api/me');app.user=me.user;app.csrf=me.csrf;await refresh();renderShell();}catch{renderLogin();}}

function renderLogin(){app.user=null;app.csrf=null;$('#app').innerHTML=`<main class="login-shell"><section class="login-hero"><div class="brand"><div class="brandmark">OP</div><div>OWNER PROPERTY</div></div><div class="hero-copy"><div class="eyebrow">● Закрытая система управления</div><h1>Контроль объектов<br>в одном месте.</h1><p>Осмотры, арендаторы, проблемы, ответственные и эксплуатационные показатели. Без договоров и лишней конфиденциальной документации.</p></div><div class="trust-row"><span class="trust-pill">Без публичной регистрации</span><span class="trust-pill">Ролевой доступ</span><span class="trust-pill">Фотоотчёты</span><span class="trust-pill">PWA</span></div></section><section class="login-panel-wrap"><form class="login-panel" id="loginForm" autocomplete="off"><div class="brandmark">OP</div><h2>Вход в систему</h2><p>Используйте учётные данные, выданные владельцем.</p><div class="field"><label>Логин</label><input name="email" required autocomplete="username"></div><div class="field"><label>Пароль</label><input name="password" type="password" required autocomplete="current-password"></div><button class="btn btn-primary btn-block" type="submit">Войти</button><div class="error" id="loginError"></div></form></section></main>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';const fd=new FormData(e.currentTarget);try{const r=await api('/api/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});app.user=r.user;app.csrf=r.csrf;app.view='dashboard';await refresh();renderShell();}catch{$('#loginError').textContent='Не удалось войти. Проверьте логин и пароль.';}};}

async function refresh(){const req=[api('/api/dashboard'),api('/api/buildings'),api('/api/tenants'),api('/api/issues')];const [dashboard,buildings,tenants,issues]=await Promise.all(req);app.data={dashboard,buildings,tenants,issues};const extra=[api('/api/notifications')];const set=['notifications'];
  if(staffMode()&&(hasPerm('issues_edit')||hasPerm('inspections_create'))){extra.push(api('/api/assignees'));set.push('assignees');}
  if(hasPerm('inspections_view')){extra.push(api('/api/inspections'),api('/api/inspection-plans'));set.push('inspections','inspectionPlans');}
  if(hasPerm('equipment_view')){extra.push(api('/api/equipment'));set.push('equipment');}
  if(hasPerm('metrics_view')){extra.push(api('/api/metrics'));set.push('metrics');}
  if(hasPerm('expenses_view')){extra.push(api('/api/expenses'));set.push('expenses');}
  if(hasPerm('security_view')){extra.push(api('/api/security'));set.push('security');}
  if(canManageStaff()){extra.push(api('/api/admin'));set.push('admin');}
  if(extra.length){const vals=await Promise.all(extra);vals.forEach((v,i)=>app.data[set[i]]=v);}
  if(app.user.role==='owner')app.data.archivedBuildings=await api('/api/buildings?archived=1');
}

function navItems(){if(app.user.role==='tenant')return[['dashboard','Главная','⌂'],['issues','Мои обращения','!'],['tenant','Моё помещение','◎']];const out=[['dashboard','Обзор','⌂']];if(hasPerm('buildings_view'))out.push(['buildings','Объекты','▦']);if(hasPerm('inspections_view'))out.push(['inspections','Осмотры','◉']);if(hasPerm('tenants_view'))out.push(['tenants','Арендаторы','◎']);if(hasPerm('issues_view'))out.push(['issues','Проблемы','!']);if(hasPerm('issues_edit'))out.push(['tasks','Задачи','✓']);if(hasPerm('equipment_view'))out.push(['equipment','Оборудование','⚙']);if(hasPerm('metrics_view'))out.push(['metrics','Показатели','↗']);if(hasPerm('expenses_view'))out.push(['expenses','Расходы','₽']);if(canManageStaff())out.push(['admin','Админ-панель','♜']);if(hasPerm('security_view'))out.push(['security','Безопасность','◆']);return out;}
function titleForView(){return(navItems().find(x=>x[0]===app.view)||['','Owner Property'])[1];}
function renderShell(){if(!app.user)return renderLogin();const nav=navItems();if(!nav.some(x=>x[0]===app.view))app.view='dashboard';const quick=staffMode()&&hasPerm('issues_edit')?'<button class="btn btn-secondary desktop-only" id="quickIssue">+ Проблема</button>':app.user.role==='tenant'?'<button class="btn btn-primary" id="quickIssue">+ Сообщить</button>':'';const unread=(app.data.notifications||[]).filter(n=>!n.readAt).length;const bell=`<button class="icon-btn notify-btn" id="notificationsBtn" title="Уведомления">♧${unread?`<span>${unread}</span>`:''}</button>`;const mobile=app.user.role==='tenant'?nav:nav.filter(x=>['dashboard','buildings','inspections','issues','admin'].includes(x[0])).slice(0,5);
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">OP</div><div>OWNER PROPERTY</div></div><nav class="nav">${nav.map(([v,l,ico])=>`<button data-view="${v}" class="${app.view===v?'active':''}"><span>${ico} &nbsp;${l}</span>${v==='issues'?`<span class="badge">${app.data.issues.filter(i=>i.status!=='done').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="user-card"><div class="user-name">${esc(app.user.name)}</div><div class="user-role">${esc(roleLabel(app.user.role))}</div></div><button class="btn btn-ghost" id="logout">Выйти</button></div></aside><main class="main"><header class="topbar"><h1 id="pageTitle">${esc(titleForView())}</h1><div class="top-actions">${quick}${bell}<button class="icon-btn" id="refreshBtn" title="Обновить">↻</button></div></header><div class="content" id="view"></div></main><nav class="mobile-nav">${mobile.map(([v,l,ico])=>`<button data-view="${v}" class="${app.view===v?'active':''}"><span class="ico">${ico}</span><span>${l}</span></button>`).join('')}</nav></div>`;
  $$('[data-view]').forEach(b=>b.onclick=()=>{app.view=b.dataset.view;renderShell();});$('#logout').onclick=async()=>{try{await api('/api/logout',{method:'POST'});}catch{}renderLogin();};$('#refreshBtn').onclick=async()=>{await refresh();renderShell();toast('Данные обновлены');};$('#quickIssue')?.addEventListener('click',()=>openIssueForm());$('#notificationsBtn')?.addEventListener('click',()=>openNotifications());renderView();}
function renderView(){const v=$('#view');$('#pageTitle').textContent=titleForView();if(app.view==='dashboard')return renderDashboard(v);if(app.view==='buildings')return renderBuildings(v);if(app.view==='tenants')return renderTenants(v);if(app.view==='tenant')return renderTenantSelf(v);if(app.view==='issues')return renderIssues(v,false);if(app.view==='tasks')return renderIssues(v,true);if(app.view==='inspections')return renderInspections(v);if(app.view==='equipment')return renderEquipment(v);if(app.view==='metrics')return renderMetrics(v);if(app.view==='expenses')return renderExpenses(v);if(app.view==='admin')return renderAdmin(v);if(app.view==='security')return renderSecurity(v);}

function issueTag(i){return`<span class="tag ${i.status==='done'?'done':i.priority==='critical'?'critical':''}">${esc(statusMap[i.status]||i.status)}</span>`;}
function issueCard(i){const b=app.data.buildings.find(x=>x.id===i.buildingId),t=app.data.tenants.find(x=>x.id===i.tenantId);return`<button class="issue-card" data-issue="${esc(i.id)}"><div class="issue-main"><div><b>${esc(i.title)}</b><span>${esc(b?.name||'')}${t?' · '+esc(t.company):''}</span></div>${issueTag(i)}</div><div class="issue-meta"><span>${esc(priorityMap[i.priority]||i.priority)}</span><span>${i.responsible?'Ответственный: '+esc(i.responsible):'Не назначен'}</span>${i.due?`<span>до ${fmtDate(i.due)}</span>`:''}</div></button>`;}
function buildingCard(b){
  const open=app.data.issues.filter(i=>i.buildingId===b.id&&i.status!=='done').length;
  const ten=app.data.tenants.filter(t=>t.buildingId===b.id).length;
  const plan=(app.data.inspectionPlans||[]).find(p=>p.buildingId===b.id);
  const ownerActions=app.user.role==='owner'?`<div class="building-actions"><button class="btn btn-secondary btn-compact" type="button" data-building-edit="${b.id}">Редактировать</button><button class="btn btn-danger btn-compact" type="button" data-building-remove="${b.id}">Удалить</button></div>`:'';
  return`<article class="building-card"><button class="building building-main" type="button" data-building="${b.id}"><div><div class="building-top"><span class="status-dot s-${b.status}"></span><b>${esc(b.name)}</b></div><div class="building-address">${esc(b.address)}</div><div class="chips"><span>${num(b.area)} м²</span><span>${ten} арендаторов</span><span>${open} проблем</span>${plan?`<span>осмотр ${fmtDate(plan.nextDue)}</span>`:''}</div></div><div class="metric-mini"><strong>${b.area?Math.round(b.occupied/b.area*100):0}%</strong><span>занято</span></div></button>${ownerActions}</article>`;
}
function bindBuildingCardActions(){
  $$('[data-building]').forEach(x=>x.onclick=()=>openBuilding(x.dataset.building));
  $$('[data-building-edit]').forEach(x=>x.onclick=e=>{e.stopPropagation();const b=app.data.buildings.find(v=>v.id===x.dataset.buildingEdit);if(b)openBuildingForm(b);});
  $$('[data-building-remove]').forEach(x=>x.onclick=e=>{e.stopPropagation();const b=app.data.buildings.find(v=>v.id===x.dataset.buildingRemove);if(b)removeBuilding(b);});
}
function tenantMini(t,b){if(!t)return'<div class="empty">Нет данных</div>';return`<div class="info-list"><div class="info-item"><div class="k">Объект</div><div class="v">${esc(b?.name||'')}</div></div><div class="info-item"><div class="k">Помещение</div><div class="v">${esc(t.unit||'—')}</div></div><div class="info-item"><div class="k">Площадь</div><div class="v">${num(t.area)} м²</div></div><div class="info-item"><div class="k">Контакт</div><div class="v">${esc(t.contact||'—')}</div></div></div>`;}
function bindIssueLinks(){$$('[data-issue]').forEach(x=>x.onclick=e=>{e.stopPropagation();openIssue(x.dataset.issue);});}

function renderDashboard(v){const d=app.data.dashboard,s=d.stats;if(app.user.role==='tenant'){const t=app.data.tenants[0],b=app.data.buildings[0];v.innerHTML=`<div class="subhead"><div><h2>Добрый день, ${esc(app.user.name)}</h2><p>${esc(b?.name||'')} · помещение ${esc(t?.unit||'')}</p></div><button class="btn btn-primary" id="tenantNewIssue">+ Сообщить о проблеме</button></div><div class="grid stats"><div class="stat"><div class="stat-label">Открытые</div><div class="stat-value">${s.open}</div><div class="stat-foot">ваши обращения</div></div><div class="stat alert"><div class="stat-label">Критические</div><div class="stat-value">${s.critical}</div><div class="stat-foot">требуют внимания</div></div><div class="stat good"><div class="stat-label">Выполнено</div><div class="stat-value">${app.data.issues.filter(i=>i.status==='done').length}</div><div class="stat-foot">за всё время</div></div></div><div class="grid two"><div class="card"><div class="card-head"><h3>Мои обращения</h3></div><div class="card-body"><div class="issue-list">${app.data.issues.slice(0,5).map(issueCard).join('')||'<div class="empty">Обращений нет</div>'}</div></div></div><div class="card"><div class="card-head"><h3>Моё помещение</h3></div><div class="card-body">${tenantMini(t,b)}</div></div></div>`;$('#tenantNewIssue').onclick=()=>openIssueForm();bindIssueLinks();return;}
  const occupied=app.data.buildings.reduce((a,b)=>a+b.occupied,0),area=app.data.buildings.reduce((a,b)=>a+b.area,0),occ=area?Math.round(occupied/area*100):0;const inspectionStat=hasPerm('inspections_view')?`<div class="stat ${s.inspectionsOverdue?'alert':'good'}"><div class="stat-label">Осмотры / 7 дней</div><div class="stat-value">${s.inspectionsDue||0}</div><div class="stat-foot">${s.inspectionsOverdue||0} просрочено</div></div>`:'';const actions=`${app.user.role==='owner'?'<button class="btn btn-primary" id="newBuilding">+ Объект</button>':''}${hasPerm('inspections_create')?'<button class="btn btn-secondary" id="newInspection">+ Осмотр</button>':''}${hasPerm('tenants_manage')?'<button class="btn btn-secondary" id="newTenant">+ Арендатор</button>':''}`;
  v.innerHTML=`<div class="subhead"><div><h2>${app.user.role==='owner'?'Портфель объектов':'Рабочая панель'}</h2><p>Сводка эксплуатации и контроля состояния</p></div><div class="action-row">${actions}</div></div><div class="grid stats"><div class="stat"><div class="stat-label">Объекты</div><div class="stat-value">${s.buildings}</div><div class="stat-foot">доступно вам</div></div><div class="stat"><div class="stat-label">Арендаторы</div><div class="stat-value">${s.tenants}</div><div class="stat-foot">${occ}% заполняемость</div></div><div class="stat alert"><div class="stat-label">Открытые проблемы</div><div class="stat-value">${s.open}</div><div class="stat-foot">${s.overdue} просрочено</div></div><div class="stat alert"><div class="stat-label">Критические</div><div class="stat-value">${s.critical}</div><div class="stat-foot">требуют контроля</div></div>${inspectionStat}${typeof s.expenses==='number'?`<div class="stat money"><div class="stat-label">Расходы</div><div class="stat-value">${(s.expenses/1e6).toFixed(2)} млн</div><div class="stat-foot">по доступным объектам</div></div>`:''}</div><div class="grid two"><div class="card"><div class="card-head"><h3>Объекты</h3></div><div class="card-body"><div class="building-list">${app.data.buildings.map(buildingCard).join('')||'<div class="empty">Объектов нет</div>'}</div></div></div><div class="card"><div class="card-head"><h3>Требует внимания</h3></div><div class="card-body"><div class="issue-list">${app.data.issues.filter(i=>i.status!=='done').sort((a,b)=>(b.priority==='critical')-(a.priority==='critical')).slice(0,6).map(issueCard).join('')||'<div class="empty">Нет открытых проблем</div>'}</div></div></div></div>`;
  $('#newBuilding')?.addEventListener('click',()=>openBuildingForm());$('#newInspection')?.addEventListener('click',()=>openInspectionForm());$('#newTenant')?.addEventListener('click',()=>openTenantForm());bindBuildingCardActions();bindIssueLinks();}

function archivedBuildingCard(b){return`<article class="building-card archived"><button class="building building-main" type="button" data-archived-building="${b.id}"><div><div class="building-top"><span class="status-dot"></span><b>${esc(b.name)}</b></div><div class="building-address">${esc(b.address)}</div><div class="chips"><span>в архиве с ${fmtDate(b.archivedAt)}</span></div></div><div class="metric-mini"><strong>Архив</strong><span>история сохранена</span></div></button><div class="building-actions"><button class="btn btn-secondary btn-compact" type="button" data-building-restore="${b.id}">Восстановить</button><button class="btn btn-danger btn-compact" type="button" data-building-delete="${b.id}">Удалить навсегда</button></div></article>`;}
function renderBuildings(v){
  const archived=app.data.archivedBuildings||[];
  v.innerHTML=`<div class="subhead"><div><h2>Объекты</h2><p>Характеристики, арендаторы, проблемы и график осмотров</p></div><div class="action-row">${app.user.role==='owner'?'<button class="btn btn-primary" id="addBuilding">+ Добавить объект</button>':''}${hasPerm('inspections_create')?'<button class="btn btn-secondary" id="buildingInspection">+ Новый осмотр</button>':''}</div></div><div class="card"><div class="card-head"><h3>Активные объекты</h3><span class="tag">${app.data.buildings.length}</span></div><div class="card-body"><div class="building-list">${app.data.buildings.map(buildingCard).join('')||'<div class="empty">Объектов пока нет. Добавьте первый реальный объект.</div>'}</div></div></div>${app.user.role==='owner'?`<div class="card archive-card" style="margin-top:16px"><div class="card-head"><h3>Архив</h3><span class="tag">${archived.length}</span></div><div class="card-body"><div class="building-list">${archived.map(archivedBuildingCard).join('')||'<div class="empty">Архив пуст</div>'}</div></div></div>`:''}`;
  $('#addBuilding')?.addEventListener('click',()=>openBuildingForm());
  $('#buildingInspection')?.addEventListener('click',()=>openInspectionForm());
  bindBuildingCardActions();
  $$('[data-archived-building]').forEach(x=>x.onclick=()=>openArchivedBuilding(x.dataset.archivedBuilding));
  $$('[data-building-restore]').forEach(x=>x.onclick=e=>{e.stopPropagation();restoreBuilding(x.dataset.buildingRestore);});
  $$('[data-building-delete]').forEach(x=>x.onclick=e=>{e.stopPropagation();deleteArchivedBuilding(x.dataset.buildingDelete);});
}
function openBuilding(id){const b=app.data.buildings.find(x=>x.id===id);if(!b)return;const tenants=app.data.tenants.filter(t=>t.buildingId===id),issues=app.data.issues.filter(i=>i.buildingId===id),plan=(app.data.inspectionPlans||[]).find(p=>p.buildingId===id),inspections=(app.data.inspections||[]).filter(i=>i.buildingId===id).slice(0,4);modal(`<div class="modal-head"><div><h3>${esc(b.name)}</h3><div class="building-address">${esc(b.address)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="info-list"><div class="info-item"><div class="k">Площадь</div><div class="v">${num(b.area)} м²</div></div><div class="info-item"><div class="k">Этажей</div><div class="v">${num(b.floors)}</div></div><div class="info-item"><div class="k">Арендаторы</div><div class="v">${tenants.length}</div></div><div class="info-item"><div class="k">Открытые проблемы</div><div class="v">${issues.filter(i=>i.status!=='done').length}</div></div><div class="info-item"><div class="k">Ответственный</div><div class="v">${esc(b.manager||'—')}</div></div><div class="info-item"><div class="k">Следующий осмотр</div><div class="v">${fmtDate(plan?.nextDue)}</div></div></div>${inspections.length?`<div class="section-title"><div><h3>Последние осмотры</h3><p>Контроль состояния объекта</p></div></div><div class="inspection-mini-list">${inspections.map(i=>`<button class="inspection-mini" data-inspection="${i.id}"><b>${fmtDateTime(i.occurredAt)}</b><span>${esc(i.inspectorName)} · ${i.createdIssueIds.length} проблем</span></button>`).join('')}</div>`:''}<div class="section-title"><div><h3>Проблемы объекта</h3></div></div><div class="issue-list">${issues.slice(0,6).map(issueCard).join('')||'<div class="empty">Проблем нет</div>'}</div></div><div class="modal-actions">${app.user.role==='owner'?'<button class="btn btn-secondary" id="editBuilding">Редактировать</button><button class="btn btn-danger" id="archiveBuilding">В архив</button>':''}${hasPerm('inspections_create')?'<button class="btn btn-primary" id="inspectBuilding">Провести осмотр</button>':''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#editBuilding')?.addEventListener('click',()=>{closeModal();openBuildingForm(b);});$('#archiveBuilding')?.addEventListener('click',()=>archiveBuilding(b));$('#inspectBuilding')?.addEventListener('click',()=>{closeModal();openInspectionForm(id);});$$('[data-inspection]').forEach(x=>x.onclick=()=>{closeModal();openInspection(x.dataset.inspection);});bindIssueLinks();}
function openBuildingForm(b=null){modal(`<form id="buildingForm"><div class="modal-head"><div><h3>${b?'Редактировать объект':'Добавить объект'}</h3><div class="building-address">Рабочие характеристики объекта — без договоров и документов</div></div><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field span2"><label>Название объекта</label><input name="name" value="${esc(b?.name||'')}" required maxlength="120"></div><div class="field span2"><label>Адрес</label><input name="address" value="${esc(b?.address||'')}" maxlength="220"></div><div class="field"><label>Площадь, м²</label><input name="area" type="number" min="0" value="${Number(b?.area||0)}"></div><div class="field"><label>Занято, м²</label><input name="occupied" type="number" min="0" value="${Number(b?.occupied||0)}"></div><div class="field"><label>Этажей</label><input name="floors" type="number" min="0" value="${Number(b?.floors||0)}"></div><div class="field"><label>Мощность, кВт</label><input name="powerKw" type="number" min="0" value="${Number(b?.powerKw||0)}"></div><div class="field"><label>Состояние</label><select name="status"><option value="ok" ${b?.status==='ok'?'selected':''}>Норма</option><option value="attention" ${b?.status==='attention'?'selected':''}>Внимание</option><option value="critical" ${b?.status==='critical'?'selected':''}>Критично</option></select></div><div class="field"><label>Ответственный</label><input name="manager" value="${esc(b?.manager||'')}"></div><div class="field span2"><label>Рабочее примечание</label><textarea name="note">${esc(b?.note||'')}</textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">${b?'Сохранить':'Создать объект'}</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#buildingForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api(b?'/api/buildings/'+encodeURIComponent(b.id):'/api/buildings',{method:b?'PATCH':'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast(b?'Объект обновлён':'Объект создан');}catch(err){toast(errorText(err));}};}
async function archiveBuilding(b){if(!confirm(`Переместить объект «${b.name}» в архив? История и связанные данные сохранятся.`))return;try{await api('/api/buildings/'+encodeURIComponent(b.id)+'/archive',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект перемещён в архив');}catch(err){toast(errorText(err));}}
async function removeBuilding(b){if(!confirm(`Удалить объект «${b.name}» из активных? Он будет перемещён в архив, история сохранится. Окончательно удалить пустой объект можно из архива.`))return;try{await api('/api/buildings/'+encodeURIComponent(b.id)+'/archive',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект перемещён в архив');}catch(err){toast(errorText(err));}}
async function restoreBuilding(id){try{await api('/api/buildings/'+encodeURIComponent(id)+'/restore',{method:'POST',body:'{}'});await refresh();closeModal();renderShell();toast('Объект восстановлен');}catch(err){toast(errorText(err));}}
async function deleteArchivedBuilding(id){const b=(app.data.archivedBuildings||[]).find(x=>x.id===id);const confirmText=prompt(`Для безвозвратного удаления пустого объекта «${b?.name||''}» введите УДАЛИТЬ`);if(confirmText!=='УДАЛИТЬ')return;try{await api('/api/buildings/'+encodeURIComponent(id),{method:'DELETE'});await refresh();closeModal();renderShell();toast('Объект удалён');}catch(err){toast(errorText(err));}}

function openArchivedBuilding(id){const b=(app.data.archivedBuildings||[]).find(x=>x.id===id);if(!b)return;modal(`<div class="modal-head"><div><h3>${esc(b.name)}</h3><div class="building-address">Архивный объект · ${esc(b.address)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="warning">Архивирование не удаляет эксплуатационную историю. Безвозвратное удаление разрешено только для объекта без связанных записей.</div><div class="info-list" style="margin-top:16px"><div class="info-item"><div class="k">Площадь</div><div class="v">${num(b.area)} м²</div></div><div class="info-item"><div class="k">Дата архивации</div><div class="v">${fmtDateTime(b.archivedAt)}</div></div></div></div><div class="modal-actions"><button class="btn btn-primary" id="restoreBuilding">Восстановить</button><button class="btn btn-danger" id="deleteBuilding">Удалить навсегда</button><button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#restoreBuilding').onclick=()=>restoreBuilding(id);$('#deleteBuilding').onclick=()=>deleteArchivedBuilding(id);}

function renderTenants(v){if(app.user.role==='tenant')return renderTenantSelf(v);v.innerHTML=`<div class="subhead"><div><h2>Арендаторы</h2><p>Помещения и эксплуатационные обращения — без договоров</p></div>${hasPerm('tenants_manage')?'<button class="btn btn-primary" id="newTenant">+ Добавить</button>':''}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Арендатор</th><th>Объект</th><th>Помещение</th><th>Площадь</th><th>Проблем</th><th></th></tr></thead><tbody>${app.data.tenants.map(t=>{const b=app.data.buildings.find(x=>x.id===t.buildingId),n=app.data.issues.filter(i=>i.tenantId===t.id&&i.status!=='done').length;return`<tr><td><b>${esc(t.company)}</b><div class="muted">${esc(t.contact||'')}</div></td><td>${esc(b?.name||'')}</td><td>${esc(t.unit||'—')}</td><td>${num(t.area)} м²</td><td>${n}</td><td><button class="link-btn" data-tenant="${t.id}">Открыть</button></td></tr>`;}).join('')}</tbody></table></div></div>`;$('#newTenant')?.addEventListener('click',()=>openTenantForm());$$('[data-tenant]').forEach(x=>x.onclick=()=>openTenant(x.dataset.tenant));}
function renderTenantSelf(v){const t=app.data.tenants[0],b=app.data.buildings[0];if(!t)return v.innerHTML='<div class="empty">Помещение не назначено</div>';v.innerHTML=`<div class="subhead"><div><h2>Моё помещение</h2><p>Только эксплуатационная информация</p></div></div><div class="hero-tenant"><div><h3>${esc(t.company)}</h3><p>${esc(b?.name||'')} · ${esc(t.unit)}</p></div><div><div class="big-area">${num(t.area)} м²</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Сведения</h3></div><div class="card-body">${tenantMini(t,b)}<div class="warning" style="margin-top:16px">В системе не хранятся договоры, банковские документы или иные конфиденциальные вложения.</div></div></div>`;}
function openTenant(id){const t=app.data.tenants.find(x=>x.id===id),b=app.data.buildings.find(x=>x.id===t?.buildingId);if(!t)return;const issues=app.data.issues.filter(i=>i.tenantId===id);const checks=(app.data.inspections||[]).flatMap(i=>(i.tenantChecks||[]).filter(c=>c.tenantId===id).map(c=>({...c,inspection:i}))).slice(0,5);modal(`<div class="modal-head"><div><h3>${esc(t.company)}</h3><div class="building-address">${esc(b?.name||'')} · ${esc(t.unit)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body">${tenantMini(t,b)}<div class="section-title"><div><h3>Проблемы арендатора</h3></div></div><div class="issue-list">${issues.map(issueCard).join('')||'<div class="empty">Проблем нет</div>'}</div>${checks.length?`<div class="section-title"><div><h3>Последние проверки при обходах</h3></div></div><div class="inspection-mini-list">${checks.map(c=>`<button class="inspection-mini" data-inspection="${c.inspection.id}"><b>${fmtDateTime(c.inspection.occurredAt)} · ${c.status==='ok'?'Норма':c.status==='problem'?'Есть проблема':'Не осмотрен'}</b><span>${esc(c.notes||'Без замечаний')}</span></button>`).join('')}</div>`:''}</div><div class="modal-actions">${hasPerm('issues_edit')?`<button class="btn btn-primary" id="tenantIssue">+ Проблема</button>`:''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantIssue')?.addEventListener('click',()=>{closeModal();openIssueForm(t.id,t.buildingId);});$$('[data-inspection]').forEach(x=>x.onclick=()=>{closeModal();openInspection(x.dataset.inspection);});bindIssueLinks();}

function renderIssues(v,tasksOnly=false){let rows=app.data.issues;if(tasksOnly&&staffMode())rows=rows.filter(i=>i.status!=='done'&&(app.user.role==='owner'||i.responsibleUserId===app.user.id||app.user.role!=='technician'));v.innerHTML=`<div class="subhead"><div><h2>${tasksOnly?'Задачи':'Проблемы'}</h2><p>${tasksOnly?'Работы, которые требуют выполнения':'Все обращения и дефекты по доступным объектам'}</p></div>${hasPerm('issues_edit')?'<button class="btn btn-primary" id="newIssue">+ Проблема</button>':''}</div><div class="card"><div class="card-body"><div class="issue-list">${rows.map(issueCard).join('')||'<div class="empty">Нет записей</div>'}</div></div></div>`;$('#newIssue')?.addEventListener('click',()=>openIssueForm());bindIssueLinks();}
function reportCard(r){return`<div class="work-report ${r.kind==='solution'?'solution':''}"><div class="report-head"><div><b>${r.kind==='solution'?'Итоговый отчёт':'Фотоотчёт по работе'}</b><div class="building-address">${fmtDateTime(r.at)}</div></div>${r.kind==='solution'?'<span class="tag done">Решено</span>':'<span class="tag">Работа</span>'}</div><div class="report-signature"><span>Исполнитель / подпись</span><strong>✓ ${esc(r.author||'Не указан')}</strong></div><div class="report-text">${esc(r.text)}</div>${(r.photos||[]).length?photoGrid(r.photos):''}${r.recordedBy?`<div class="report-recorded">Зафиксировал в системе: ${esc(r.recordedBy)}</div>`:''}</div>`;}
function tenantAcceptancePanel(i){const h=i.acceptanceHistory||[],latest=h[h.length-1];if(i.status==='awaiting_acceptance'){return app.user.role==='tenant'?`<div class="tenant-acceptance waiting"><div><span>ТРЕБУЕТСЯ ВАШЕ ПОДТВЕРЖДЕНИЕ</span><strong>Исполнитель сообщил, что проблема устранена</strong><p>Проверьте результат и подтвердите либо верните в работу.</p></div><div class="accept-actions"><button class="btn btn-primary" id="tenantAccept">✓ Проблема устранена</button><button class="btn btn-danger" id="tenantReject">Проблема осталась</button></div></div>`:`<div class="tenant-acceptance waiting"><div><span>ОЖИДАЕТ ПОДТВЕРЖДЕНИЯ АРЕНДАТОРА</span><strong>Фотоотчёт отправлен на проверку</strong></div></div>`;}if(i.status==='done'&&i.tenantAcceptedAt)return`<div class="tenant-acceptance accepted"><div><span>ПРИНЯТО АРЕНДАТОРОМ</span><strong>✓ ${esc(i.tenantAcceptedBy||'Арендатор')}</strong><p>${fmtDateTime(i.tenantAcceptedAt)}</p></div></div>`;if(latest?.decision==='rejected')return`<div class="tenant-acceptance rejected"><div><span>РЕЗУЛЬТАТ НЕ ПРИНЯТ</span><strong>Проблема возвращена в работу</strong><p>${fmtDateTime(latest.at)} · ${esc(latest.comment||'')}</p></div>${latest.photos?.length?photoGrid(latest.photos):''}</div>`;return'';}
function issueEvidenceComparison(i){const before=(i.photos||[]).filter(p=>p.kind==='problem')[0],solution=(i.reports||[]).filter(r=>r.kind==='solution').slice(-1)[0],after=solution?.photos?.slice(-1)[0];const pane=(label,p,cls)=>p?`<a class="compare-pane ${cls}" href="${esc(p.url)}" target="_blank"><div class="compare-label">${label}</div><img src="${esc(p.url)}" alt="${label}"><div class="compare-meta"><b>${fmtDateTime(p.at)}</b><span>${esc(p.actor||'')}</span></div></a>`:`<div class="compare-pane ${cls} empty"><div class="compare-label">${label}</div><div class="compare-placeholder"><strong>Фото пока нет</strong></div></div>`;return`<div class="evidence-compare">${pane('ДО',before,'before')}<div class="compare-arrow">→</div>${pane('ПОСЛЕ',after,'after')}</div>${solution?`<div class="solution-signoff"><div><span>${i.status==='awaiting_acceptance'?'ОЖИДАЕТ ПОДТВЕРЖДЕНИЯ':'РЕШЕНИЕ'}</span><strong>✓ ${esc(solution.author)}</strong></div><div><b>${fmtDateTime(solution.at)}</b><small>подпись и время</small></div></div>`:''}`;}
function openIssue(id){const i=app.data.issues.find(x=>x.id===id);if(!i)return;const b=app.data.buildings.find(x=>x.id===i.buildingId),t=app.data.tenants.find(x=>x.id===i.tenantId),problemPhotos=(i.photos||[]).filter(p=>p.kind==='problem');modal(`<div class="modal-head"><div><h3>${esc(i.title)}</h3><div class="building-address">${esc(b?.name||'')}${t?' · '+esc(t.company):''}${i.sourceInspectionId?' · выявлено при осмотре':''}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body">${issueEvidenceComparison(i)}${tenantAcceptancePanel(i)}<div class="info-list" style="margin-top:16px"><div class="info-item"><div class="k">Статус</div><div class="v">${esc(statusMap[i.status]||i.status)}</div></div><div class="info-item"><div class="k">Приоритет</div><div class="v">${esc(priorityMap[i.priority]||i.priority)}</div></div><div class="info-item"><div class="k">Ответственный</div><div class="v">${esc(i.responsible||'Не назначен')}</div></div><div class="info-item"><div class="k">Срок</div><div class="v">${fmtDate(i.due)}</div></div></div><div class="section-title"><div><h3>Фото проблемы</h3><p>Исходное состояние с датой и автором</p></div>${(app.user.role==='tenant'||hasPerm('issues_edit'))?'<button class="btn btn-secondary" id="addProblemPhotos">+ Фото</button>':''}</div>${photoGrid(problemPhotos)}<div class="section-title"><div><h3>Отчёты по решению</h3></div>${hasPerm('issues_edit')?'<button class="btn btn-secondary" id="addReport">+ Отчёт</button>':''}</div><div class="reports-list">${(i.reports||[]).map(reportCard).join('')||'<div class="photo-empty">Отчётов пока нет</div>'}</div><div class="section-title"><div><h3>История</h3></div></div><div class="log">${(i.timeline||[]).slice().reverse().map(x=>`<div class="log-row"><div class="time">${fmtDateTime(x.at)}</div><div><b>${esc(x.actor||'Система')}</b></div><div>${esc(x.text)}</div></div>`).join('')}</div></div><div class="modal-actions">${hasPerm('issues_edit')?'<button class="btn btn-secondary" id="editIssue">Назначить / изменить</button><button class="btn btn-primary" id="quickSolve">✓ Закрыть с фотоотчётом</button>':''}<button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#addProblemPhotos')?.addEventListener('click',()=>{closeModal();openIssuePhotoForm(i);});$('#addReport')?.addEventListener('click',()=>{closeModal();openReportForm(i,false);});$('#quickSolve')?.addEventListener('click',()=>{closeModal();openReportForm(i,true);});$('#editIssue')?.addEventListener('click',()=>{closeModal();openIssueEdit(i);});$('#tenantAccept')?.addEventListener('click',()=>{closeModal();openTenantDecisionForm(i,'accepted');});$('#tenantReject')?.addEventListener('click',()=>{closeModal();openTenantDecisionForm(i,'rejected');});}

function inspectionDueClass(p){if(!p?.nextDue)return'';const d=new Date(p.nextDue+'T23:59:59'),now=new Date();if(d<now)return'overdue';if((d-now)/864e5<=7)return'due';return'ok';}
function renderInspections(v){const plans=app.data.inspectionPlans||[],inspections=app.data.inspections||[];v.innerHTML=`<div class="subhead"><div><h2>Осмотры объектов</h2><p>Регламентный обход с фото 3–4 сторон здания и проверкой арендаторов</p></div>${hasPerm('inspections_create')?'<button class="btn btn-primary" id="newInspection">+ Провести осмотр</button>':''}</div><div class="grid inspection-plans">${plans.map(p=>{const b=app.data.buildings.find(x=>x.id===p.buildingId),cls=inspectionDueClass(p),ins=(app.data.assignees||app.data.admin?.users||[]).find(x=>x.id===p.inspectorUserId);return`<div class="inspection-plan ${cls}"><div><span>${cls==='overdue'?'ПРОСРОЧЕНО':cls==='due'?'НА ЭТОЙ НЕДЕЛЕ':'ПО ПЛАНУ'}</span><h3>${esc(b?.name||p.buildingId)}</h3><p>Периодичность: каждые ${p.frequencyDays} дней</p></div><div class="inspection-plan-date"><strong>${fmtDate(p.nextDue)}</strong><small>${esc(ins?.name||'Инспектор не назначен')}</small></div></div>`;}).join('')}</div><div class="card"><div class="card-head"><h3>История осмотров</h3><span class="tag">${inspections.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Объект</th><th>Инспектор</th><th>Состояние</th><th>Арендаторы</th><th>Создано проблем</th><th></th></tr></thead><tbody>${inspections.map(i=>{const b=app.data.buildings.find(x=>x.id===i.buildingId);return`<tr><td>${fmtDateTime(i.occurredAt)}</td><td><b>${esc(b?.name||'')}</b></td><td>${esc(i.inspectorName)}</td><td>${esc(inspectionStatusMap[i.overallCondition]||i.overallCondition)}</td><td>${i.tenantChecks?.length||0}</td><td>${i.createdIssueIds?.length||0}</td><td><button class="link-btn" data-inspection="${i.id}">Отчёт</button></td></tr>`;}).join('')||'<tr><td colspan="7"><div class="empty">Осмотров пока нет</div></td></tr>'}</tbody></table></div></div>`;$('#newInspection')?.addEventListener('click',()=>openInspectionForm());$$('[data-inspection]').forEach(x=>x.onclick=()=>openInspection(x.dataset.inspection));}
function openInspection(id){const i=(app.data.inspections||[]).find(x=>x.id===id);if(!i)return;const b=app.data.buildings.find(x=>x.id===i.buildingId);modal(`<div class="modal-head"><div><h3>Осмотр · ${esc(b?.name||'')}</h3><div class="building-address">${fmtDateTime(i.occurredAt)} · ${esc(i.inspectorName)}</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="inspection-sign"><span>ПОДПИСЬ ИНСПЕКТОРА</span><strong>✓ ${esc(i.signature||i.inspectorName)}</strong><small>${fmtDateTime(i.createdAt)}</small></div><div class="section-title"><div><h3>Вид объекта снаружи</h3><p>Фото 3–4 сторон здания</p></div></div>${photoGrid(i.exteriorPhotos||[],true)}<div class="section-title"><div><h3>Общее состояние</h3></div></div><div class="info-list"><div class="info-item"><div class="k">Оценка</div><div class="v">${esc(inspectionStatusMap[i.overallCondition]||i.overallCondition)}</div></div><div class="info-item"><div class="k">Комментарий</div><div class="v">${esc(i.notes||'Без замечаний')}</div></div></div>${i.buildingFinding?`<div class="inspection-finding critical"><div><span>ПРОБЛЕМА ОБЪЕКТА</span><strong>${esc(i.buildingFinding.title)}</strong><p>${esc(i.buildingFinding.notes||'')}</p></div>${photoGrid(i.buildingFinding.photos||[])}${i.buildingFinding.issueId?`<button class="btn btn-secondary" data-issue="${i.buildingFinding.issueId}">Открыть созданную проблему</button>`:''}</div>`:''}<div class="section-title"><div><h3>Осмотр арендаторов</h3></div></div><div class="tenant-check-list">${(i.tenantChecks||[]).map(c=>{const t=app.data.tenants.find(x=>x.id===c.tenantId);return`<div class="tenant-check ${c.status}"><div class="tenant-check-head"><div><b>${esc(t?.company||c.tenantId)}</b><span>${esc(t?.unit||'')}</span></div><strong>${c.status==='ok'?'✓ Норма':c.status==='problem'?'! Проблема':'— Не осмотрен'}</strong></div>${c.notes?`<p>${esc(c.notes)}</p>`:''}${c.photos?.length?photoGrid(c.photos):''}${c.issueId?`<button class="btn btn-secondary" data-issue="${c.issueId}">Открыть проблему</button>`:''}</div>`;}).join('')||'<div class="empty">Арендаторы не проверялись</div>'}</div></div><div class="modal-actions"><button class="btn btn-ghost" data-close>Закрыть</button></div>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);bindIssueLinks();}
function tenantCheckRows(buildingId){const ts=app.data.tenants.filter(t=>t.buildingId===buildingId);return ts.map(t=>`<div class="inspection-tenant-row" data-check-tenant="${t.id}"><div class="tenant-row-title"><b>${esc(t.company)}</b><span>${esc(t.unit)} · ${num(t.area)} м²</span></div><div class="form-grid"><div class="field"><label>Результат</label><select data-field="status"><option value="ok">Норма</option><option value="problem">Есть проблема</option><option value="not_checked">Не осмотрен</option></select></div><div class="field"><label>Категория проблемы</label><select data-field="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field span2"><label>Комментарий / что обнаружено</label><textarea data-field="notes" maxlength="1000" placeholder="Если всё нормально — можно оставить пустым. При проблеме опишите дефект."></textarea></div><div class="field"><label>Приоритет</label><select data-field="priority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div><div class="field"><label>Фото при проблеме</label><input data-field="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div></div>`).join('')||'<div class="empty">На объекте нет арендаторов</div>';}
function openInspectionForm(buildingId=''){const opts=app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===buildingId?'selected':''}>${esc(b.name)}</option>`).join(''),initial=buildingId||app.data.buildings[0]?.id||'';const dt=new Date();dt.setMinutes(dt.getMinutes()-dt.getTimezoneOffset());const local=dt.toISOString().slice(0,16);modal(`<form id="inspectionForm"><div class="modal-head"><div><h3>Регламентный осмотр объекта</h3><div class="building-address">Фотофиксация, проверка арендаторов и автоматическая раздача проблем</div></div><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="warning">Не фотографируйте документы, персональные данные и экраны арендаторов. В отчёт попадает только состояние здания, оборудования и эксплуатационные дефекты.</div><div class="form-grid" style="margin-top:16px"><div class="field"><label>Объект</label><select name="buildingId" id="inspectionBuilding" required>${opts}</select></div><div class="field"><label>Дата и время осмотра</label><input name="occurredAt" type="datetime-local" value="${local}" required></div><div class="field"><label>Общее состояние</label><select name="overallCondition"><option value="ok">Норма</option><option value="attention">Есть замечания</option><option value="critical">Критично</option></select></div><div class="field span2"><label>Общий комментарий</label><textarea name="notes" maxlength="2000" placeholder="Состояние территории, входных групп, фасада, кровли по визуальному осмотру и т. п."></textarea></div></div><div class="section-title"><div><h3>Фото объекта с 3–4 сторон</h3><p>Первые три фотографии обязательны</p></div></div><div class="inspection-photo-fields">${['Фасад / сторона 1','Фасад / сторона 2','Фасад / сторона 3','Фасад / сторона 4 (необязательно)'].map((x,n)=>`<div class="field"><label>${x}</label><input id="exterior${n+1}" type="file" accept="image/jpeg,image/png,image/webp" ${n<3?'required':''}></div>`).join('')}</div><div class="section-title"><div><h3>Проблема общего имущества</h3><p>Заполняется только если при внешнем осмотре найден дефект</p></div></div><div class="inspection-building-finding"><div class="form-grid"><div class="field span2"><label>Что обнаружено</label><input id="buildingFindingTitle" maxlength="160" placeholder="Например: разрушение плитки у входа"></div><div class="field"><label>Категория</label><select id="buildingFindingCategory"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field"><label>Приоритет</label><select id="buildingFindingPriority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div><div class="field span2"><label>Комментарий</label><textarea id="buildingFindingNotes"></textarea></div><div class="field span2"><label>Фото дефекта</label><input id="buildingFindingPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div></div><div class="section-title"><div><h3>Осмотр арендаторов</h3><p>Для каждого помещения отметьте результат</p></div></div><div id="inspectionTenantRows">${tenantCheckRows(initial)}</div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Завершить осмотр и раздать проблемы</button></div></form>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#inspectionBuilding').onchange=e=>{$('#inspectionTenantRows').innerHTML=tenantCheckRows(e.target.value);};$('#inspectionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const exteriorPhotos=[];for(let n=1;n<=4;n++){const inp=$('#exterior'+n);const photos=await filesToPayload(inp);if(photos[0])exteriorPhotos.push({side:`Сторона ${n}`,photo:photos[0]});}if(exteriorPhotos.length<3)throw new Error('Нужно минимум 3 фотографии объекта с разных сторон');const tenantChecks=[];for(const row of $$('[data-check-tenant]')){const status=$('[data-field="status"]',row).value,notes=$('[data-field="notes"]',row).value,category=$('[data-field="category"]',row).value,priority=$('[data-field="priority"]',row).value,photos=await filesToPayload($('[data-field="photos"]',row));if(status==='problem'&&!notes.trim())throw new Error('Для проблемы арендатора нужно описание');if(status==='problem'&&!photos.length)throw new Error('Для проблемы арендатора нужно фото');tenantChecks.push({tenantId:row.dataset.checkTenant,status,notes,category,priority,photos});}const bfTitle=$('#buildingFindingTitle').value.trim();let buildingFinding=null;if(bfTitle){const photos=await filesToPayload($('#buildingFindingPhotos'));if(!photos.length)throw new Error('Для проблемы объекта приложите фото');buildingFinding={title:bfTitle,category:$('#buildingFindingCategory').value,priority:$('#buildingFindingPriority').value,notes:$('#buildingFindingNotes').value,photos};}const payload={buildingId:fd.get('buildingId'),occurredAt:new Date(fd.get('occurredAt')).toISOString(),overallCondition:fd.get('overallCondition'),notes:fd.get('notes'),exteriorPhotos,tenantChecks,buildingFinding};const r=await api('/api/inspections',{method:'POST',body:JSON.stringify(payload)});await refresh();closeModal();renderShell();toast(`Осмотр сохранён. Создано проблем: ${r.createdIssueIds?.length||0}`);}catch(err){toast(errorText(err));}};}

function renderEquipment(v){const rows=app.data.equipment||[];v.innerHTML=`<div class="subhead"><div><h2>Оборудование</h2><p>Минимальный технический реестр без документов</p></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Оборудование</th><th>Объект</th><th>Система</th><th>Модель</th><th>Состояние</th><th>Следующее ТО</th></tr></thead><tbody>${rows.map(e=>{const b=app.data.buildings.find(x=>x.id===e.buildingId);return`<tr><td><b>${esc(e.name)}</b></td><td>${esc(b?.name||'')}</td><td>${esc(e.system)}</td><td>${esc(e.model)}</td><td>${e.status==='ok'?'Норма':'Внимание'}</td><td>${fmtDate(e.nextService)}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
function renderMetrics(v){const metrics=app.data.metrics||[],b1=app.data.buildings[0],series=metrics.filter(m=>m.buildingId===b1?.id),max=Math.max(...series.map(x=>x.electricity),1);v.innerHTML=`<div class="subhead"><div><h2>Показатели</h2><p>Электричество, вода, тепло и аномалии</p></div></div><div class="card"><div class="card-head"><h3>Электричество · ${esc(b1?.name||'')}</h3></div><div class="card-body"><div class="metric-bars">${series.map(m=>`<div class="bar-row"><span>${esc(m.month)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.round(m.electricity/max*100)}%"></div></div><span class="value">${num(m.electricity)}</span></div>`).join('')}</div></div></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Объект</th><th>Месяц</th><th>Электричество</th><th>Вода</th><th>Тепло</th></tr></thead><tbody>${metrics.map(m=>{const b=app.data.buildings.find(x=>x.id===m.buildingId);return`<tr><td>${esc(b?.name||'')}</td><td>${esc(m.month)}</td><td>${num(m.electricity)} кВт⋅ч</td><td>${num(m.water)} м³</td><td>${num(m.heat)} Гкал</td></tr>`;}).join('')}</tbody></table></div></div>`;}
function renderExpenses(v){const ex=app.data.expenses||[];v.innerHTML=`<div class="subhead"><div><h2>Эксплуатационные расходы</h2><p>Агрегированные рабочие показатели — без договоров и счетов</p></div></div><div class="grid stats">${ex.map(x=>{const b=app.data.buildings.find(q=>q.id===x.buildingId);return`<div class="stat money"><div class="stat-label">${esc(b?.name||'')}</div><div class="stat-value">${(x.total/1e6).toFixed(2)} млн</div><div class="stat-foot">${Math.round(x.total/(b?.area||1))} ₽ / м²</div></div>`;}).join('')}</div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Объект</th><th>Всего</th><th>Электричество</th><th>Вода</th><th>Тепло</th><th>Уборка</th><th>Охрана</th><th>Ремонт</th></tr></thead><tbody>${ex.map(x=>{const b=app.data.buildings.find(q=>q.id===x.buildingId);return`<tr><td><b>${esc(b?.name||'')}</b></td><td>${money(x.total)}</td><td>${money(x.electricity)}</td><td>${money(x.water)}</td><td>${money(x.heat)}</td><td>${money(x.cleaning)}</td><td>${money(x.security)}</td><td>${money(x.repair)}</td></tr>`;}).join('')}</tbody></table></div></div>`;}

function renderAdmin(v){const a=app.data.admin;if(!a)return v.innerHTML='<div class="empty">Нет доступа</div>';const s=a.stats,staff=a.users.filter(u=>!['owner','tenant'].includes(u.role)),staffMap=new Map(a.users.map(u=>[u.id,u]));v.innerHTML=`<div class="subhead"><div><h2>Админ-панель владельца</h2><p>Сотрудники, роли, графики осмотров, маршрутизация и статистика</p></div><button class="btn btn-primary" id="addStaff">+ Сотрудник</button></div><div class="grid stats"><div class="stat"><div class="stat-label">Активные сотрудники</div><div class="stat-value">${s.activeStaff}</div><div class="stat-foot">${s.disabledStaff} отключено</div></div><div class="stat alert"><div class="stat-label">Открытые проблемы</div><div class="stat-value">${s.openIssues}</div><div class="stat-foot">по всем объектам</div></div><div class="stat"><div class="stat-label">Осмотров за 7 дней</div><div class="stat-value">${s.inspections7d}</div><div class="stat-foot">${s.duePlans} планов на неделе</div></div><div class="stat"><div class="stat-label">Среднее решение</div><div class="stat-value">${s.avgResolutionHours||0} ч</div><div class="stat-foot">по закрытым проблемам</div></div><div class="stat alert"><div class="stat-label">Возвратов арендаторами</div><div class="stat-value">${s.rejected30d}</div><div class="stat-foot">за 30 дней</div></div></div><div class="card"><div class="card-head"><h3>Сотрудники и доступы</h3><span class="tag">учётные записи закрытого контура</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Объекты</th><th>Открытых задач</th><th>Статус</th><th></th></tr></thead><tbody>${staff.map(u=>{const w=s.workload.find(x=>x.userId===u.id);return`<tr><td><b>${esc(u.name)}</b><div class="muted">${esc(u.email)}</div></td><td>${esc(roleLabel(u.role))}</td><td>${(u.buildingIds||[]).map(id=>esc(app.data.buildings.find(b=>b.id===id)?.name||id)).join(', ')||'—'}</td><td>${w?.open||0}</td><td><span class="staff-status ${u.active?'active':'disabled'}">${u.active?'Активен':'Отключён'}</span></td><td><div class="row-actions"><button class="link-btn" data-edit-staff="${u.id}">Права</button><button class="link-btn" data-reset-staff="${u.id}">Пароль</button><button class="link-btn ${u.active?'danger-link':''}" data-toggle-staff="${u.id}">${u.active?'Уволить / отключить':'Восстановить'}</button></div></td></tr>`;}).join('')}</tbody></table></div></div><div class="grid two" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Автоматическое распределение проблем</h3><button class="link-btn" id="addRoute">+ Маршрут</button></div><div class="card-body"><div class="route-list">${a.routingRules.filter(r=>r.active!==false).map(r=>{const b=r.buildingId==='*'?'Все объекты':app.data.buildings.find(x=>x.id===r.buildingId)?.name||r.buildingId,u=staffMap.get(r.responsibleUserId);return`<div class="route-row"><div><b>${esc(r.category)}</b><span>${esc(b)}</span></div><strong>→ ${esc(u?.name||'Не назначен')}</strong></div>`;}).join('')}</div></div></div><div class="card"><div class="card-head"><h3>Графики еженедельных осмотров</h3></div><div class="card-body"><div class="route-list">${a.inspectionPlans.map(p=>{const b=app.data.buildings.find(x=>x.id===p.buildingId),u=staffMap.get(p.inspectorUserId);return`<button class="route-row plan-row" data-plan="${p.buildingId}"><div><b>${esc(b?.name||p.buildingId)}</b><span>каждые ${p.frequencyDays} дней · следующий ${fmtDate(p.nextDue)}</span></div><strong>${esc(u?.name||'Не назначен')}</strong></button>`;}).join('')}</div></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Нагрузка сотрудников</h3></div><div class="card-body"><div class="workload-grid">${s.workload.map(w=>`<div class="workload-card"><span>${esc(roleLabel(w.role))}</span><strong>${esc(w.name)}</strong><div><b>${w.open}</b> открытых задач · <b>${w.inspections}</b> осмотров / 30 дн.</div></div>`).join('')}</div></div></div>`;$('#addStaff').onclick=()=>openStaffForm();$$('[data-edit-staff]').forEach(x=>x.onclick=()=>openStaffForm(x.dataset.editStaff));$$('[data-reset-staff]').forEach(x=>x.onclick=()=>resetStaffPassword(x.dataset.resetStaff));$$('[data-toggle-staff]').forEach(x=>x.onclick=()=>toggleStaff(x.dataset.toggleStaff));$('#addRoute').onclick=()=>openRouteForm();$$('[data-plan]').forEach(x=>x.onclick=()=>openPlanForm(x.dataset.plan));}
function permissionsChecks(selected=[]){const labels={dashboard_view:'Обзор',buildings_view:'Объекты',tenants_view:'Видеть арендаторов',tenants_manage:'Добавлять арендаторов',issues_view:'Видеть проблемы',issues_edit:'Назначать и решать проблемы',inspections_view:'Видеть осмотры',inspections_create:'Проводить осмотры',equipment_view:'Оборудование',metrics_view:'Показатели',expenses_view:'Расходы',staff_manage:'Управлять сотрудниками',security_view:'Безопасность'};const perms=app.data.admin.permissions;return`<div class="permission-grid">${perms.map(p=>`<label class="perm"><input type="checkbox" name="permissions" value="${p}" ${selected.includes(p)?'checked':''}><span><b>${esc(labels[p]||p)}</b><small>${esc(p)}</small></span></label>`).join('')}</div>`;}
function openStaffForm(id=''){const a=app.data.admin,u=id?a.users.find(x=>x.id===id):null,role=u?.role||'manager',selected=u?.permissions||a.roleDefaults[role]||[];modal(`<form id="staffForm"><div class="modal-head"><div><h3>${u?'Права сотрудника':'Добавить сотрудника'}</h3><div class="building-address">Доступ выдаётся только владельцем; публичной регистрации нет</div></div><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Имя</label><input name="name" value="${esc(u?.name||'')}" required></div>${u?'':`<div class="field"><label>Логин / email</label><input name="email" type="email" required></div>`}<div class="field"><label>Роль</label><select name="role" id="staffRole">${a.roles.map(r=>`<option value="${r}" ${r===role?'selected':''}>${esc(roleLabel(r))}</option>`).join('')}</select></div></div><div class="section-title"><div><h3>Доступ к объектам</h3></div></div><div class="permission-grid">${app.data.buildings.map(b=>`<label class="perm"><input type="checkbox" name="buildingIds" value="${b.id}" ${(u?.buildingIds||app.data.buildings.map(x=>x.id)).includes(b.id)?'checked':''}><span><b>${esc(b.name)}</b><small>${esc(b.address)}</small></span></label>`).join('')}</div><div class="section-title"><div><h3>Права</h3><p>Можно дать только необходимые функции</p></div></div><div id="staffPermissions">${permissionsChecks(selected)}</div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">${u?'Сохранить права':'Создать сотрудника'}</button></div></form>`,true);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#staffRole').onchange=e=>{if(!u)$('#staffPermissions').innerHTML=permissionsChecks(a.roleDefaults[e.target.value]||[]);};$('#staffForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={name:fd.get('name'),role:fd.get('role'),buildingIds:fd.getAll('buildingIds'),permissions:fd.getAll('permissions')};if(!u)payload.email=fd.get('email');try{if(u){await api('/api/staff/'+encodeURIComponent(u.id),{method:'PATCH',body:JSON.stringify(payload)});toast('Права сотрудника обновлены');}else{const r=await api('/api/staff',{method:'POST',body:JSON.stringify(payload)});closeModal();showTempPassword(r.user,r.temporaryPassword);await refresh();renderShell();return;}await refresh();closeModal();renderShell();}catch(err){toast(errorText(err));}};}
function showTempPassword(user,pwd){modal(`<div class="modal-head"><h3>Сотрудник создан</h3><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="success-note">Временный пароль показывается только сейчас. Передайте его сотруднику безопасным способом.</div><div class="credential-box"><span>${esc(user.email)}</span><strong>${esc(pwd)}</strong></div></div><div class="modal-actions"><button class="btn btn-primary" id="copyPwd">Скопировать пароль</button><button class="btn btn-ghost" data-close>Готово</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#copyPwd').onclick=async()=>{try{await navigator.clipboard.writeText(pwd);toast('Пароль скопирован');}catch{toast('Скопируйте пароль вручную');}};}
async function toggleStaff(id){const u=app.data.admin.users.find(x=>x.id===id);if(!u)return;if(u.active&&!confirm(`Отключить доступ сотруднику ${u.name}? Его активные сессии будут завершены.`))return;try{await api('/api/staff/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({active:!u.active})});await refresh();renderShell();toast(u.active?'Доступ отключён':'Доступ восстановлен');}catch(err){toast(errorText(err));}}
async function resetStaffPassword(id){const u=app.data.admin.users.find(x=>x.id===id);if(!u)return;if(!confirm(`Сбросить пароль ${u.name}? Все его активные сессии завершатся.`))return;try{const r=await api('/api/staff/'+encodeURIComponent(id)+'/reset-password',{method:'POST',body:'{}'});showTempPassword(u,r.temporaryPassword);}catch(err){toast(errorText(err));}}
function openRouteForm(){const staff=app.data.admin.users.filter(u=>u.active&&!['owner','tenant'].includes(u.role));modal(`<form id="routeForm"><div class="modal-head"><h3>Маршрут проблемы</h3><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId"><option value="*">Все объекты</option>${app.data.buildings.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Категория</label><select name="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field span2"><label>Автоматически назначать</label><select name="responsibleUserId">${staff.map(u=>`<option value="${u.id}">${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}</select></div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#routeForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/routing-rules',{method:'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast('Маршрут сохранён');}catch(err){toast(errorText(err));}};}
function openPlanForm(buildingId){const p=app.data.admin.inspectionPlans.find(x=>x.buildingId===buildingId),b=app.data.buildings.find(x=>x.id===buildingId),staff=app.data.admin.users.filter(u=>u.active&&!['owner','tenant'].includes(u.role));modal(`<form id="planForm"><div class="modal-head"><div><h3>График осмотров</h3><div class="building-address">${esc(b?.name||'')}</div></div><button class="icon-btn" data-close type="button">×</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Периодичность, дней</label><input name="frequencyDays" type="number" min="1" max="90" value="${p.frequencyDays}" required></div><div class="field"><label>Следующий осмотр</label><input name="nextDue" type="date" value="${esc(p.nextDue)}" required></div><div class="field span2"><label>Инспектор</label><select name="inspectorUserId">${staff.map(u=>`<option value="${u.id}" ${u.id===p.inspectorUserId?'selected':''}>${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}</select></div></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close type="button">Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#planForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/inspection-plans/'+encodeURIComponent(buildingId),{method:'PATCH',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast('График обновлён');}catch(err){toast(errorText(err));}};}

function openNotifications(){const rows=app.data.notifications||[];modal(`<div class="modal-head"><div><h3>Уведомления</h3><div class="building-address">Новые назначения и результаты по проблемам</div></div><button class="icon-btn" data-close>×</button></div><div class="modal-body"><div class="notification-list">${rows.map(n=>`<button class="notification-row ${n.readAt?'':'unread'}" ${n.issueId?`data-notify-issue="${esc(n.issueId)}"`:''}><div><b>${esc(n.title)}</b><span>${fmtDateTime(n.at)}</span></div><p>${esc(n.text)}</p></button>`).join('')||'<div class="empty">Уведомлений пока нет</div>'}</div></div><div class="modal-actions"><button class="btn btn-ghost" data-close>Закрыть</button></div>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$$('[data-notify-issue]').forEach(x=>x.onclick=()=>{const id=x.dataset.notifyIssue;closeModal();openIssue(id);});const unread=rows.filter(n=>!n.readAt).map(n=>n.id);if(unread.length){api('/api/notifications/read',{method:'POST',body:JSON.stringify({ids:unread})}).then(()=>{const at=new Date().toISOString();for(const n of rows)if(unread.includes(n.id))n.readAt=at;}).catch(()=>{});}}

function renderSecurity(v){const s=app.data.security;if(!s)return;v.innerHTML=`<div class="subhead"><div><h2>Безопасность</h2><p>Контроль сессий и действий пользователей</p></div></div><div class="grid security-grid"><div class="security-card"><span>Активные сессии</span><strong>${s.sessions}</strong></div><div class="security-card"><span>Ошибки входа / минута</span><strong>${s.failedLastMinute}</strong></div><div class="security-card"><span>Публичная регистрация</span><strong style="color:var(--green);font-size:20px">Выключена</strong></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Журнал действий</h3><span class="tag">только чтение</span></div><div class="card-body"><div class="log">${s.log.map(x=>`<div class="log-row"><div class="time">${esc(x.at)}</div><div><b>${esc(x.actor)}</b></div><div>${esc(x.event)}</div></div>`).join('')}</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Политика данных</h3></div><div class="card-body"><div class="info-list"><div class="info-item"><div class="k">Договоры и счета</div><div class="v">Не хранятся</div></div><div class="info-item"><div class="k">Фото осмотров</div><div class="v">Только приватный API</div></div><div class="info-item"><div class="k">PWA-кэш</div><div class="v">Только оболочка</div></div><div class="info-item"><div class="k">Уволенные сотрудники</div><div class="v">Сессии завершаются сразу</div></div></div></div></div>`;}

function modal(html,wide=false){closeModal();const bg=document.createElement('div');bg.id='modal';bg.className='modal-backdrop';bg.innerHTML=`<div class="modal ${wide?'modal-wide':''}">${html}</div>`;document.body.appendChild(bg);bg.onclick=e=>{if(e.target===bg)closeModal();};}
function closeModal(){$('#modal')?.remove();}
function openTenantForm(){const opts=app.data.buildings.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('');modal(`<form id="tenantForm"><div class="modal-head"><h3>Добавить арендатора</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="warning">Не прикладывайте договоры, счета или иные конфиденциальные документы. Только рабочие сведения.</div><div class="form-grid"><div class="field"><label>Объект</label><select name="buildingId" required>${opts}</select></div><div class="field"><label>Название</label><input name="company" required></div><div class="field"><label>Помещение</label><input name="unit"></div><div class="field"><label>Площадь, м²</label><input name="area" type="number" min="1" required></div><div class="field"><label>Этаж</label><input name="floor" type="number" min="0"></div><div class="field"><label>Контакт</label><input name="contact"></div><div class="field"><label>Телефон</label><input name="phone"></div><div class="field"><label>Ответственный собственника</label><input name="ownerResponsible"></div><div class="field span2"><label>Рабочее примечание</label><textarea name="note"></textarea></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Добавить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/tenants',{method:'POST',body:JSON.stringify(o)});await refresh();closeModal();renderShell();toast('Арендатор добавлен');}catch(err){toast(errorText(err));}};}
function assigneeOptions(selected=''){return`<option value="">Не назначен</option>${(app.data.assignees||app.data.admin?.users||[]).filter(u=>u.active!==false&&u.role!=='tenant'&&u.role!=='owner').map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${esc(u.name)} · ${esc(roleLabel(u.role))}</option>`).join('')}`;}
function openIssueForm(tenantId='',buildingId=''){const ownerish=staffMode(),tenantOptions=app.data.tenants.map(t=>`<option value="${t.id}" ${t.id===tenantId?'selected':''}>${esc(t.company)} · ${esc(t.unit)}</option>`).join(''),buildingOptions=app.data.buildings.map(b=>`<option value="${b.id}" ${b.id===buildingId?'selected':''}>${esc(b.name)}</option>`).join('');modal(`<form id="issueForm"><div class="modal-head"><h3>${ownerish?'Создать проблему':'Сообщить о проблеме'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid">${ownerish?`<div class="field"><label>Объект</label><select name="buildingId" required>${buildingOptions}</select></div><div class="field"><label>Арендатор</label><select name="tenantId"><option value="">Общая проблема объекта</option>${tenantOptions}</select></div>`:''}<div class="field span2"><label>Что произошло</label><input name="title" required maxlength="160"></div><div class="field"><label>Категория</label><select name="category"><option>Протечка</option><option>Электрика</option><option>Вентиляция</option><option>Водоснабжение</option><option>Двери</option><option>Уборка</option><option>Другое</option></select></div><div class="field"><label>Приоритет</label><select name="priority"><option value="normal">Обычный</option><option value="high">Высокий</option><option value="critical">Критический</option><option value="low">Низкий</option></select></div>${ownerish?`<div class="field"><label>Ответственный (можно оставить авто)</label><select name="responsibleUserId">${assigneeOptions()}</select></div><div class="field"><label>Срок</label><input name="due" type="date"></div>`:''}<div class="field span2"><label>Фотографии проблемы</label><input id="issuePhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="field-help">До 5 фото. Дата, время и автор сохраняются автоматически.</div></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Создать</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#issueForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{const photos=await filesToPayload($('#issuePhotos')),created=await api('/api/issues',{method:'POST',body:JSON.stringify(o)});if(photos.length)await api('/api/issues/'+encodeURIComponent(created.id)+'/photos',{method:'POST',body:JSON.stringify({kind:'problem',photos})});await refresh();closeModal();renderShell();toast('Проблема создана');}catch(err){toast(errorText(err));}};}
function openIssuePhotoForm(i){modal(`<form id="issuePhotoForm"><div class="modal-head"><h3>Добавить фото проблемы</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="field"><label>Фотографии</label><input id="moreIssuePhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#issuePhotoForm').onsubmit=async e=>{e.preventDefault();try{const photos=await filesToPayload($('#moreIssuePhotos'));if(!photos.length)throw new Error('Выберите фотографию');await api('/api/issues/'+encodeURIComponent(i.id)+'/photos',{method:'POST',body:JSON.stringify({kind:'problem',photos})});await refresh();closeModal();openIssue(i.id);toast('Фото добавлены');}catch(err){toast(errorText(err));}};}
function openReportForm(i,closeMode=false){const suggested=i.responsible||i.executor||app.user.name;modal(`<form id="reportForm"><div class="modal-head"><h3>Отчёт по решению</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="form-grid"><div class="field span2"><label>Кто выполнял работу / подпись</label><input name="author" value="${esc(suggested)}" required></div><div class="field span2"><label>Что сделано</label><textarea name="text" required maxlength="1500"></textarea></div><div class="field span2"><label>Фотоотчёт</label><input id="reportPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></div><div class="field span2"><label class="check-row"><input name="markDone" type="checkbox" value="1" ${closeMode?'checked':''}><span><b>Проблема полностью решена</b><small>Для арендатора результат уйдёт на подтверждение.</small></span></label></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Добавить отчёт</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#reportForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const photos=await filesToPayload($('#reportPhotos'));if(!photos.length)throw new Error('Добавьте хотя бы одно фото');await api('/api/issues/'+encodeURIComponent(i.id)+'/reports',{method:'POST',body:JSON.stringify({author:fd.get('author'),text:fd.get('text'),markDone:fd.get('markDone')==='1',photos})});await refresh();closeModal();openIssue(i.id);toast('Фотоотчёт сохранён');}catch(err){toast(errorText(err));}};}
function openTenantDecisionForm(i,decision){const accepted=decision==='accepted';modal(`<form id="tenantDecisionForm"><div class="modal-head"><h3>${accepted?'Подтвердить устранение':'Проблема осталась'}</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="field"><label>${accepted?'Комментарий':'Что осталось нерешённым'}</label><textarea name="comment" ${accepted?'':'required'}></textarea></div><div class="field"><label>Фото (необязательно)</label><input id="tenantDecisionPhotos" type="file" accept="image/jpeg,image/png,image/webp" multiple></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn ${accepted?'btn-primary':'btn-danger'}" type="submit">${accepted?'Подтвердить':'Вернуть в работу'}</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#tenantDecisionForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{const photos=await filesToPayload($('#tenantDecisionPhotos'));await api('/api/issues/'+encodeURIComponent(i.id)+'/tenant-decision',{method:'POST',body:JSON.stringify({decision,comment:fd.get('comment')||'',photos})});await refresh();closeModal();openIssue(i.id);toast(accepted?'Проблема принята':'Проблема возвращена в работу');}catch(err){toast(errorText(err));}};}
function openIssueEdit(i){modal(`<form id="issueEdit"><div class="modal-head"><h3>Назначить / изменить</h3><button class="icon-btn" type="button" data-close>×</button></div><div class="modal-body"><div class="warning">Закрывайте проблему только через итоговый фотоотчёт.</div><div class="form-grid" style="margin-top:16px"><div class="field"><label>Статус</label><select name="status">${Object.entries(statusMap).filter(([k])=>k!=='done').map(([k,val])=>`<option value="${k}" ${i.status===k?'selected':''}>${val}</option>`).join('')}</select></div><div class="field"><label>Приоритет</label><select name="priority">${Object.entries(priorityMap).map(([k,val])=>`<option value="${k}" ${i.priority===k?'selected':''}>${val}</option>`).join('')}</select></div><div class="field span2"><label>Ответственный</label><select name="responsibleUserId">${assigneeOptions(i.responsibleUserId)}</select></div><div class="field"><label>Исполнитель / подрядчик</label><input name="executor" value="${esc(i.executor||'')}"></div><div class="field"><label>Срок</label><input name="due" type="date" value="${esc(i.due||'')}"></div><div class="field"><label>Стоимость</label><input name="cost" type="number" min="0" value="${Number(i.cost||0)}"></div></div></div><div class="modal-actions"><button class="btn btn-ghost" type="button" data-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></form>`);$$('[data-close]').forEach(x=>x.onclick=closeModal);$('#issueEdit').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/issues/'+encodeURIComponent(i.id),{method:'PATCH',body:JSON.stringify(o)});await refresh();closeModal();openIssue(i.id);toast('Назначение обновлено');}catch(err){toast(errorText(err));}};}
function errorText(err){const m={THREE_OR_FOUR_EXTERIOR_PHOTOS_REQUIRED:'Нужно приложить 3–4 фотографии объекта с разных сторон',TENANT_PROBLEM_DESCRIPTION_REQUIRED:'Опишите найденную проблему арендатора',TENANT_PROBLEM_PHOTO_REQUIRED:'К проблеме арендатора обязательно приложите фото',BUILDING_PROBLEM_PHOTO_REQUIRED:'К проблеме объекта обязательно приложите фото',PHOTO_REQUIRED:'Фото обязательно',EMAIL_EXISTS:'Такой логин уже существует',FORBIDDEN:'Недостаточно прав для этого действия',BUILDING_NAME_REQUIRED:'Укажите название объекта',BUILDING_MUST_BE_ARCHIVED:'Сначала переместите объект в архив',BUILDING_HAS_RELATED_DATA:'Нельзя удалить объект: к нему привязаны эксплуатационные записи'};return m[err.code]||err.message||'Не удалось выполнить действие';}

boot();
